from enum import Enum
class ReuseMode(str,Enum): DIRECT='DIRECT_REUSE'; ADAPTER='ADAPTER_REUSE'; PATTERN='PATTERN_REUSE'; NONE='NO_REUSE'
class CompatibilityStatus(str,Enum): PASS='PASS'; WARN='WARN'; FAIL='FAIL'; PENDING='PENDING'
class AdapterFamily(str,Enum): TIME='TIME'; REFERENCE='REFERENCE'; HUNT='HUNT'; DIVERGENCE='DIVERGENCE'; CONFIRMATION='CONFIRMATION'; LIFECYCLE='LIFECYCLE'; VISUAL='VISUAL'; EXECUTION='EXECUTION'
class SourceContext(str,Enum): EXP0017='EXP0017'; EXP0018='EXP0018'; STRATEGY_FACTORY='STRATEGY_FACTORY'
class HealthState(str,Enum): READY='READY'; DEGRADED='DEGRADED'; BLOCKED='BLOCKED'
class Direction(str,Enum): NONE='NONE'; BULLISH='BULLISH'; BEARISH='BEARISH'
class HuntSide(str,Enum): NONE='NONE'; HIGH='HIGH'; LOW='LOW'; BOTH='BOTH'
class PairState(str,Enum): NONE='NONE'; A_ONLY='A_ONLY'; B_ONLY='B_ONLY'; BOTH='BOTH'; UNAVAILABLE='UNAVAILABLE'
class ConfirmationOutcome(str,Enum): NONE='NONE'; CONFIRMED='CONFIRMED'; INVALIDATED_DOUBLE_HUNT='INVALIDATED_DOUBLE_HUNT'; NO_SIGNAL_AT_CLOSE='NO_SIGNAL_AT_CLOSE'; UNAVAILABLE='UNAVAILABLE'; ROLE_CHANGED='ROLE_CHANGED'; MISSED_CLOSE='MISSED_CLOSE'
